public class AgeValidatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static boolean accepts(int age) {
        try {
            AgeValidator.validate(age);
            return true;
        } catch (AgeValidator.InvalidAgeException e) {
            return false;
        }
    }

    public static void main(String[] args) {
        try {
            check("validate(0) accepts the lower bound", true, accepts(0));
            check("validate(130) accepts the upper bound", true, accepts(130));
            check("validate(42) accepts a normal age", true, accepts(42));
            try {
                AgeValidator.validate(-1);
                check("validate(-1) throws InvalidAgeException", true, false);
            } catch (AgeValidator.InvalidAgeException e) {
                check("validate(-1) throws InvalidAgeException", true, true);
                check("getBadAge() after validate(-1)", -1, e.getBadAge());
            }
            try {
                AgeValidator.validate(200);
                check("validate(200) throws InvalidAgeException", true, false);
            } catch (AgeValidator.InvalidAgeException e) {
                check("validate(200) throws InvalidAgeException", true, true);
                check("getBadAge() after validate(200)", 200, e.getBadAge());
            }
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
